uml_elements.plantuml_source:
@startuml
class Book {
  +id: String
  +title: String
  +publishedDate: Date
  +available: Boolean
}
class BookService {
  +list(): Book
  +create(title: String, publishedDate: Date, available: Boolean): Book
  +update(id: String): Book
  +remove(id: String): void
}
class BookRepository {
  +list(): Book
  +findById(id: String): Book
  +create(value: Book): Book
  +update(id: String): Book
  +remove(id: String): void
}
class Member {
  +id: String
  +name: String
  +borrowLimit: Integer
}
class MemberService {
  +list(): Member
  +create(name: String, borrowLimit: Integer): Member
  +update(id: String): Member
  +remove(id: String): void
}
class MemberRepository {
  +list(): Member
  +findById(id: String): Member
  +create(value: Member): Member
  +update(id: String): Member
  +remove(id: String): void
}
BookService --> BookRepository : uses
BookRepository --> Book : persists
MemberService --> MemberRepository : uses
MemberRepository --> Member : persists
@enduml
